import { makeConfidentialPool as makePoolForStubs } from '../dapp/confidential-pool.js';
import { sha256 } from '@noble/hashes/sha256';

secp.etc.hmacSha256Sync = (k, ...m) => hmac(sha256, k, secp.etc.concatBytes(...m));
const require = createRequire(import.meta.url);
const { chromium } = require(process.env.PLAYWRIGHT || '/Users/z/zFi/node_modules/playwright-core');
const DAPP = new URL('../dapp/', import.meta.url).pathname;
// Borrow reports under each step's own line (#bw-s1…#bw-s4) as well as the sheet's: read them all.
const bwText = (page) => page.evaluate((s) => [...document.querySelectorAll(s)].map((e) => e.textContent).join(' '), '#bw-status, #bw-s1, #bw-s2, #bw-s3, #bw-s4');
const ONLY = new Set((process.argv[2] || 'airdrop,links,swapurl,swapfield,hints,hxbridge,hxbridgec,flowpanel,ux,apr,farmgate,pair,farm,reinvest,buy,tacfarm,sell,v1,v1refuse,wrapform,devsend,device,devtac,devtacdraft,devtacacct,borrow,bonds,bondadd,mainbond,locks,redeem,repay,csend,tacsend,selfexit,selfmore,selflocks,selfsplit,makepub,farmjoin,lpsend,rsend,swapahead,zapfirst,swapown,routeahead,connectkey,copylink,zapway,zapcredit,zapresume,zapresume2,lponly,hxsendname,pace,farmpos,hxpos,farmsteps,farmzap,farmzapeth,lpvoucher,fastzap,farmzapdrop,farmzapsplit,farmbondnote,farmqueue,farmheld,farmreuse,hxtip,farmexit,farmclaim,farmself,farmworth,swap,shield,keys,tacopen,saved,bitcoin,passkey,acct,devmove,btc,bridge,clearedfind,bridgedeep,bridgemerge,bridgeall,bridgeto,bridgepub,xobridge,xbring,xtbridge,xtring,xtfind,hxout,hxlink,hxpanel,hxweek,hxsell,hxlater,hxsats,devtokpool,hxsendpool,hxexit,hxsendpp,hxdry,hxnudge,hxfold,hxteth,hxsend,hxsendcheck,hxplace,hxsendtac,hxsendwallet,hxsendways,hxborrow,hxvault,hxvaultkey,hxborrowback,tradelinks,pxs,pxsback,fmchips,pts,ptsview,retention,activity,receipts,stats,dash,tacdeposit,openact,openfarm,heldoff,provecap,heldborrow,vaultborrow,rewardspriv,rewardsout,rewardsjoin,bridgemove,bridgepresses,bridgefindhere,holdborrow,hxheld,holdpublic,selffund,selfeth,selfprove,exitahead,selfdevice,wrapfirst,poolkeep,poolwait,poolstale,poolfunds,tacvoucher,relaystate,relayfail,selfwallet,slowline').split(','));
const FORK = process.argv[3] || 'https://mainnet.gateway.tenderly.co';
const SHOTS = process.env.SHOTS || null;
const PORT = 20000 + Math.floor(Math.random() * 2000), WEB = PORT + 1;
const ANVIL = `http://127.0.0.1:${PORT}`;
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const word = (v) => BigInt(v).toString(16).padStart(64, '0');
const addrWord = (a) => a.toLowerCase().replace(/^0x/, '').padStart(64, '0');
// The EIP-712 digest of typed data (types, primaryType, domain, message), for the typed data the page signs besides a permit (Permit2's).
function typedDigest(d) {
  const T = d.types, k = (x) => Buffer.from(keccak_256(typeof x === 'string' ? Buffer.from(x) : x));
  const dep = (n, seen = new Set()) => { if (seen.has(n) || !T[n]) return seen; seen.add(n); for (const f of T[n]) dep(f.type.replace(/\[\]$/, ''), seen); return seen; };
  const sig = (n) => `${n}(${T[n].map((f) => `${f.type} ${f.name}`).join(',')})`;
  const encType = (n) => sig(n) + [...dep(n)].filter((x) => x !== n).sort().map(sig).join('');
  const val = (t, v) => (T[t] ? hash(t, v) : t === 'string' ? k(v) : t === 'address' ? Buffer.from(addrWord(v), 'hex') : Buffer.from(word(BigInt(v)), 'hex'));
  const hash = (n, v) => k(Buffer.concat([k(encType(n)), ...T[n].map((f) => val(f.type, v[f.name]))]));
  return k(Buffer.concat([Buffer.from([0x19, 0x01]), hash('EIP712Domain', d.domain), hash(d.primaryType, d.message)]));
}

// A stand-in proof's public values for a wrap op: the layout of ConfidentialPool's PublicValues as far as a page reads it, consuming the
// op's own deposit and inserting its own leaf (the pages check a wrap proof is for their note before they use it).
const STUB_POOL = makePoolForStubs({ secp, keccak256: keccak_256, sha256 }), STUB_CETH = '0x3cba71e1114af183cdeacc6b8457a474d17529fd28704480ca799d0d03126f34';
const STUB_CTAC = '0xf0bbe868af10c6c67652a99709bf32048d1aa7194efe3e9a1ef1bde43f94762b';
// A wrap op read back from its program input (sp1-stdin.js): the asset, then the value (an 8-byte entry), then cx, cy and owner, each a
// 32-byte entry under its own length.
function wrapOpFromStdin(stdin, asset) {
  const h = String(stdin).replace(/^0x/, '').toLowerCase(), a = String(asset).replace(/^0x/, '').toLowerCase(), at = h.indexOf(a);
  if (at < 0) return null;
  let p = at + 64 + 16;
  const value = BigInt('0x' + (h.slice(p, p + 16).match(/../g) || []).reverse().join('')); p += 16;
  const f = () => { p += 32; const x = '0x' + h.slice(p, p + 64); p += 64; return x; };
  return { asset: '0x' + a, value: value.toString(), cx: f(), cy: f(), owner: f() };
}
function wrapPv(op) { return wrapPvOf(STUB_POOL.leaf(op.asset, op.cx, op.cy, op.owner), depositIdOf(op)); }
// A deposit swapped in one proof: the swap's note inserted, its deposit consumed.
function wrapSwapPv(op) {
  const d = Number(op.direction) === 0, inA = d ? op.assetA : op.assetB, outA = d ? op.assetB : op.assetA;
  return wrapPvOf(STUB_POOL.leaf(outA, op.out.cx, op.out.cy, op.out.owner), depositIdOf({ asset: inA, value: op.amountIn, cx: op.deposit.cx, cy: op.deposit.cy, owner: op.deposit.owner }));
}
// A wrap's public values as the pool reads them: one leaf inserted, one deposit consumed.
function wrapPvOf(leaf, dep) {
  const w = (v) => BigInt(v).toString(16).padStart(64, '0'), head = Array(40).fill(w(0));
  head[4] = w(40 * 32); head[5] = w(42 * 32); head[3] = w(44 * 32); head[7] = w(45 * 32);
  return '0x' + w(32) + head.join('') + w(1) + leaf.replace(/^0x/, '') + w(1) + dep.replace(/^0x/, '') + w(0) + w(0);
}
const anvil = spawn('anvil', ['--port', String(PORT), '--fork-url', FORK, '--chain-id', '1', '--silent', '--no-rate-limit'], { stdio: 'ignore' });
process.on('exit', () => anvil.kill('SIGKILL'));
const rpc = async (method, params = []) => {
  const r = await (await fetch(ANVIL, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ jsonrpc: '2.0', id: 1, method, params }) })).json();
  if (r.error) throw Object.assign(new Error(r.error.message), { data: r.error.data });
  return r.result;
};
for (let i = 0; ; i++) { try { await rpc('eth_chainId'); break; } catch { if (i > 120) throw new Error('anvil did not start'); await sleep(500); } }

const TYPES = { '.js': 'text/javascript', '.html': 'text/html; charset=utf-8', '.json': 'application/json', '.css': 'text/css', '.wasm': 'application/wasm', '.svg': 'image/svg+xml', '.png': 'image/png', '.woff2': 'font/woff2', '.zkey': 'application/octet-stream' };
const server = createServer((req, res) => {
  let f = normalize(join(DAPP, decodeURIComponent(new URL(req.url, 'http://x').pathname)));
  if (!f.startsWith(DAPP)) { res.writeHead(403); return res.end(); }
  if (existsSync(f) && statSync(f).isDirectory()) f = join(f, 'index.html');
  if (!existsSync(f)) { res.writeHead(404); return res.end(); }
  res.writeHead(200, { 'content-type': TYPES[extname(f)] || 'application/octet-stream' });
  res.end(readFileSync(f));
}).listen(WEB);

const RPC_HOSTS = ['ethereum-rpc.publicnode.com', 'eth.drpc.org', '1rpc.io', 'mainnet.gateway.tenderly.co', 'cloudflare-eth.com', 'rpc.flashbots.net',
  'rpc.mevblocker.io', 'eth-mainnet.public.blastapi.io', 'ethereum-json-rpc.stakely.io', 'eth.rpc.blxrbdn.com', '1.rpc.thirdweb.com'];   // and the TAC vaults' own (vault/chain.js)
const submits = [], refused = [], relays = [], walletTxs = [];
// What the wallet stub does beyond sending: takes EIP-5792 batches (batch), cannot sign typed data (noTyped), turns it down (rejectTyped),
// or signs a permit for another amount than the one asked (badPermit). The batches it was sent, and where each one landed.
const walletWays = { batch: false, noTyped: false, rejectTyped: false, badPermit: false }, batches = [], batchHashes = {};
let gatewayOnce = false;                                          // the next relay meets a gateway timeout (devmove)
// Submits the relay refuses before taking them, as it does once the day's free settles are used up.
let refuseSubmits = 0;
// What a relayed job reports when it fails (the default stands for a settle the page could not see through).
let statusError = 'stubbed in the fork check';
