  for (const t0 = Date.now(); submits.length - b2 < want && Date.now() - t0 < 240000;) await sleep(500);
  await sleep(3000);
  const fees = submits.slice(b2).map((b) => BigInt(b.op?.fee ?? b.fee ?? -1));
  const ladder = (v) => v.toString().replace(/0+$/, '').length <= 2;
