    ok(seen.some((t) => /^Step 1 of 3 · .*harvest/.test(t)) && seen.some((t) => /^Step 2 of 3 · .*unbond/.test(t)) && seen.some((t) => /^Step 3 of 3 · .*liquidity out/.test(t)), `farmexit: each step names itself as it runs (${seen.map((t) => t.slice(0, 28)).join(' | ')})`);
